import {typeRecommendations as recommendations} from './type-recommendations100.mjs';
import {cleanAge,ageVersion} from './age100.mjs';
import {wordingVersion} from './wording100.mjs';
import {normalizeRecord,supportedVersions,previousVersion,validPriorAnswer} from './record100.mjs';
import {questions,byId,partNames,questionnaireVersion,validAnswer,sanitizeAnswers,answeredCount,answerLabel,featureLabels,domainDefs} from './data100.mjs';
import {model,profileFromAnswers,classifyAnswers,readings,preferenceGaps,pair,recommendationReasons,demoAnswers} from './engine100.mjs';
const KEY='suddenly-see-survey-100-v1',app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,saved=null;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{storageOK=false;}
const normalized=normalizeRecord(saved);let previousResponses=normalized.previousResponses;
let ageProfile=cleanAge(saved?.ageProfile);
let answers=normalized.answers,index=Number.isInteger(saved?.index)?Math.max(0,Math.min(99,saved.index)):0,view=['home','intro','survey','result'].includes(saved?.view)?saved.view:'home';
let imported=null,demo=null,counterpart=null,ownerIndex=null,completing=!!saved?.completing,toastTimer;
const current=()=>imported?.answers??demo?.answers??answers;
const currentAge=()=>cleanAge(imported?imported.ageProfile:demo?demo.ageProfile:ageProfile);
function ageInputs(which='all'){const p=currentAge();return `<div class="age-fields"><p><strong>나이 정보 (선택)</strong></p><p class="caption">만 나이 19~100세로 입력해 주세요. 본인 확인 기능은 아니에요. 나이는 성향 점수에 더하지 않아요.</p>${which!=='wish'?`<label>내 만 나이<input type="number" min="19" max="100" step="1" data-age="age" value="${p.age??''}" placeholder="미입력"></label>`:''}${which!=='self'?`<label>원하는 상대의 최소 만 나이<input type="number" min="19" max="100" step="1" data-age="min" value="${p.min??''}" placeholder="미입력"></label><label>원하는 상대의 최대 만 나이<input type="number" min="19" max="100" step="1" data-age="max" value="${p.max??''}" placeholder="미입력"></label><p class="caption">97번에서 나이를 고른 경우에만 이 범위를 엄격하게 적용해요. 범위 양끝 나이도 포함해요. 범위나 상대 나이가 없으면 추천을 보류해요.</p>`:''}</div>`;}
function openAge(){const d=dialog('나이 정보와 희망 범위',ageInputs()+'<button class="button primary" data-age-done>저장하고 결과 보기</button>');d.querySelector('[data-age-done]').onclick=()=>{d.close();move('result');};}
document.addEventListener('change',e=>{const field=e.target.dataset?.age;if(!field)return;const target=imported??demo;if(target)target.ageProfile={...currentAge(),[field]:e.target.value===''?null:Number(e.target.value)};else ageProfile={...ageProfile,[field]:e.target.value===''?null:Number(e.target.value)};persist();});
const measured=a=>questions.filter(q=>q.id<=60&&validAnswer(q.id,a[q.id])&&a[q.id]!=='unknown').length;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function persist(){if(imported||demo)return;try{localStorage.setItem(KEY,JSON.stringify({questionnaireVersion,modelVersion:model.version,previousResponses,completing,wordingVersion,ageVersion,ageProfile:cleanAge(ageProfile),answers,index,view}));storageOK=true;}catch{storageOK=false;}}
function move(next,scroll=true){view=next;persist();render();if(scroll){window.scrollTo(0,0);document.querySelector('main h1')?.focus({preventScroll:true});}}
function header(){return `<header class="site-header"><button class="brand" data-action="home"><span class="brand-star" aria-hidden="true">✳</span><span><span class="brand-name">Suddenly I See</span><span class="brand-sub">A LITTLE CLOSER TO YOU</span></span></button><span class="prototype">100 QUESTIONS · EXPERIENCE 15</span></header>${!storageOK?'<p class="save-alert">브라우저 자동 저장을 사용할 수 없어요. 결과를 파일이나 텍스트로 보관해 주세요.</p>':''}`;}
function flower(type,size=''){let i=model.prototypes.findIndex(p=>p.type===type);if(i<0)i=0;return `<div class="flower-character ${size}" style="--col:${i%4};--row:${Math.floor(i/4)};--crop-y:${[100,460,810,1165][Math.floor(i/4)]/1536*100}%" role="img" aria-label="${esc(model.prototypes[i].flower)} 꽃 캐릭터"><img src="./assets/flower-characters-v2.png" alt="" loading="lazy"></div>`;}
function method(){return `<details class="method"><summary>검사·유형·추천은 어떻게 계산하나요?</summary><div class="method-grid"><div><h3>나의 성향과 원하는 상대를 따로</h3><p>파트 1은 나의 성격·관계·생활 60문항, 파트 2는 상대 선호 35문항과 추천 선호 5문항이에요. 상대 선호만 바꿔도 나의 유형은 그대로예요.</p></div><div><h3>16개 초기 대표 프로필과 비교</h3><p>유형은 37문항에서 얻은 25개 정보를 8개 영역으로 묶어 비교해요. 이전처럼 네 문항만으로 정하지 않아요. 정확한 동점은 공동 후보로, 근소한 차이는 경계 성향으로 보여줘요.</p></div><div><h3>연구를 따르는 부분</h3><p>Mini-IPIP의 다섯 성격 요인과 역채점, ECR-RS 일반형의 불안·회피 채점 방향을 참고해요. 한국어 번안 문항의 타당성은 별도 확인이 필요해요.</p><p><a href="https://www.ipip.ori.org/MiniIPIPKey.htm" target="_blank" rel="noopener">Mini-IPIP 채점표</a> · <a href="https://labs.psychology.illinois.edu/~rcfraley/measures/relstructures.htm" target="_blank" rel="noopener">ECR-RS 지침</a></p></div><div><h3>우리가 정한 부분</h3><p>꽃 16유형·대표값·영역 비중·경계 3점·추천 기준은 테스트용 서비스 규칙이에요. 유형은 진단, 점수는 백분위나 연애 성공 확률이 아니에요.</p></div><div><h3>양쪽이 원하는 모습을 함께</h3><p>A가 원하는 모습과 B의 실제 답변, B가 원하는 모습과 A의 실제 답변을 각각 계산하고 조화평균으로 합쳐요. 양쪽 50점 이상, 비교 정보 70% 이상인 사례를 추천해요. 흡연·자녀 계획·종교·문신·나이 중 직접 정한 제외 조건만 엄격히 적용해요.</p></div><div><h3>추천 유형과 실제 매칭을 구분</h3><p>참고 유형은 성격·관계 방식으로 최대3개를 보여줘요. 나이·흡연·종교 등 실제 상대 조건이나 매칭 통과 기준으로 숨기지 않아요. 실제 두 사람을 비교할 때만 별도 조건 검사를 적용해요.</p><p>정서·애착·흡연·종교·문신·예산은 꽃 유형의 우열을 만들지 않아요. 종교·문신은 자체 생활 선호 문항이며 미응답을 없음으로 보지 않아요. 생활과 상대 선호는 분석·추천에 사용해요. 실제 키링 연결은 아직 없는 웹 체험이에요.</p></div></div></details>`;}
function footer(){return `${method()}<footer class="site-footer"><span>Some connections begin with knowing yourself.</span><span>${questionnaireVersion} · ${model.version}</span></footer>`;}
function home(){const n=answeredCount(answers);return `${header()}<main id="main" class="page"><section class="hero100"><div><p class="eyebrow">YOUR OWN WAY TO CONNECT</p><h1 tabindex="-1">마음을 알아가면,<br>연결도 달라질까요?</h1><p class="hero-copy">나의 모습과 내가 편안하게 느끼는 상대.<br>100개의 질문으로 관계의 여러 면을 살펴보고,<br>나와 가까운 꽃과 개인별 이야기를 만나보세요.</p><div class="hero-actions"><button class="button primary" data-action="start">${n===100?'내 결과 다시 보기':n?`${n}/100 이어서 검사하기`:'나의 마음 알아보기'} →</button><button class="button secondary" data-action="demo">예시 결과 먼저 보기</button><button class="button secondary" data-action="import">결과 불러오기</button></div><p class="caption">답변은 서버로 전송하지 않고 이 브라우저에 저장해요.<br>이전 답변은 보존해요. 종교·문신 기준이 바뀐 4문항은 해당하는 답변만 다시 확인해요. <a href="./legacy.html">이전 검사·결과 보기</a></p></div><div class="home-flower"><span class="home-emblem" aria-hidden="true">✳</span><p class="handwriting">a little closer<br>to yourself</p></div></section><section class="stats100"><div><strong>100</strong><span>나이 정보는 선택 입력</span></div><div><strong>60 + 40</strong><span>나의 모습 · 원하는 상대</span></div><div><strong>16</strong><span>같은 꽃도 서로 다른 이야기</span></div></section><section class="parts100"><article><p class="eyebrow">PART 01</p><h2>나의 성향과 생활</h2><p>기본 성격, 가까운 관계 경험, 실제로 선택하는 생활과 관계 방식.</p><small>60문항 · 나를 설명하는 정보</small></article><article><p class="eyebrow">PART 02</p><h2>내가 원하는 상대</h2><p>편안하게 느끼는 상대의 행동과 생활, 중요하게 생각하는 추천 기준.</p><small>40문항 · 상대에 대한 선호</small></article></section><section class="catalog-home"><p class="eyebrow">SIXTEEN FLOWERS</p><h2>어떤 꽃과 가까울까요?</h2><div class="mini-catalog">${model.prototypes.map(p=>`<button data-demo="${p.type}">${flower(p.type)}<strong>${p.type}</strong><span>${p.korean}</span></button>`).join('')}</div><p class="caption">꽃을 누르면 해당 초기 대표 프로필의 가상 예시 결과를 볼 수 있어요.</p></section></main>${footer()}`;}
function intro(){const part=index<60?0:1;return `${header()}<main id="main" class="page intro100"><section><p class="eyebrow">PART 0${part+1}</p><h1 tabindex="-1">${partNames[part]}</h1><p class="lead">${part===0?'정답보다, 평소의 나에게 가까운 답을 골라주세요.':'좋은 사람의 정답이 아니라, 내가 편안하게 느끼는 상대를 떠올려주세요.'}</p><p>${part===0?'기본 성격 20문항, 가까운 관계 경험 9문항, 생활·관계 행동 31문항이에요.':'원하는 상대 35문항과 중요 영역·차이 수용 등 추천 선호 5문항이에요. 이 답변은 나의 꽃 유형에 합산하지 않아요.'}</p><button class="button primary" data-action="part-start">파트 ${part+1} 시작하기 →</button><button class="link-button" data-action="home">처음 화면으로</button></section></main>${footer()}`;}
function option(q,value,label){const a=current()[q.id],multi=q.kind==='multi'&&value!=='any'&&value!=='unknown',checked=Array.isArray(a)?a.includes(value):a===value;return `<label class="choice100 ${checked?'checked':''}"><input id="q${q.id}-${esc(value)}" name="q${q.id}" type="${multi?'checkbox':'radio'}" data-question="${q.id}" data-value="${esc(value)}" ${checked?'checked':''}><span><b class="choice-marker" aria-hidden="true">${checked?'✓':''}</b>${esc(label)}</span></label>`;}
function survey(){const q=questions[index],part=index<60?0:1,n=answeredCount(current());return `${header()}<main id="main" class="page survey100"><div class="survey-top"><span>PART ${part+1} · ${partNames[part]}</span><button class="link-button" data-action="navigator">답변 돌아보기</button></div><div class="progress100" role="progressbar" aria-label="전체 답변 진행" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><i style="width:${n}%"></i></div><div class="question-meta"><span>${q.id} / 100</span><span>${part===0?`${q.id} / 60`:`${q.id-60} / 40`} · ${part===0?'나의 모습':'원하는 상대·추천 선호'}</span></div><section class="question100"><p class="eyebrow">${part===0?'ABOUT ME':'SOMEONE I FEEL AT EASE WITH'}</p><h1 tabindex="-1">${esc(q.text)}</h1><p class="question-hint">${esc(q.hint??'지금의 생각에 가까운 답을 골라주세요.')}</p><fieldset><legend class="sr-only">${esc(q.text)}</legend><div class="choices100">${q.options.map(o=>option(q,o.value,o.label)).join('')}${q.allowAny?option(q,'any',q.id===97?'제외 조건 없음':q.id===96?'특히 우선하는 영역 없이 고르게':'크게 상관없음'):''}${option(q,'unknown','판단하기 어려움 · 응답하지 않음')}</div></fieldset>${q.id===60?ageInputs('self'):q.id===97?ageInputs('wish'):''}<p class="source100">${esc(q.source)}</p><div class="survey-buttons"><button class="button secondary" data-action="previous" ${index===0?'disabled':''}>← 이전</button><button class="button primary" data-action="next" ${!validAnswer(q.id,current()[q.id])?'disabled':''}>${index===99?'내 결과 보기':index===59?'파트 2로':'다음'} →</button></div><p class="caption">선택한 답변은 자동 저장돼요. 나중에 수정할 수 있어요.</p></section></main>`;}
function evidence(list){return `<details class="evidence100"><summary>이렇게 읽은 근거</summary>${list.map(e=>`<p><a href="#" data-go="${e.id}">Q${e.id}</a> ${esc(e.question)}<br><strong>${esc(e.answer)}</strong></p>`).join('')}</details>`;}
function scoreBars(f){return Object.entries(f).filter(([k])=>!k.startsWith('q')).map(([k,v])=>`<div class="score100"><div><span>${featureLabels[k]}</span><b>${v===null?'미측정':Math.round(v)}</b></div><div class="score-track"><i style="width:${v??0}%"></i></div></div>`).join('');}
function scoreEvidence(){return `<p class="caption">0~100은 응답 평균을 변환한 표시값이에요. 백분위가 아니며, 높을수록 좋은 성격이라는 의미도 아니에요. 하위척도 문항이 누락되면 해당 점수를 표시하지 않아요.</p>`;}
function typeCard(p){return `<article class="match-card100 type-reference100"><div class="match-heading">${flower(p.type,'small')}<div><p class="eyebrow">성향 참고 유형</p><h3>${esc(p.type)}</h3><p>${esc(p.korean)}</p></div></div><p class="match-numbers">${p.referenceMode==='self-similarity'?'나와 닮은 정도':'원하는 성향과 가까운 정도'} <b>${Math.round(p.score)}/100</b></p><p class="caption">비교에 사용한 성향 정보 ${p.rows.length}개 · 실제 상대 조건은 확인하지 않은 참고 정보예요.</p>${p.reasons.map(r=>`<div class="reason100"><h4>${esc(r.title)}</h4><p>${esc(r.text)}</p></div>`).join('')}<details class="evidence100"><summary>유형 비교 근거</summary><p>성격·관계 방식의25개 유형 정보에 해당하는 응답만 비교해요. 상대 선호가 있으면 그 선호와 대표값을 비교하고, 없으면 내 유형 판정의 유사성을 사용해요. 실제 상대 매칭의50점·70% 기준과 제외 조건을 적용하지 않아요.</p>${p.domains.map(d=>`<p>${esc(d.name)} · 선호 가까움 ${Math.round(d.fit*100)} · 비중 ${d.weight}</p>`).join('')}</details></article>`;}
function pairCard(p,name,synthetic=false){const r=p.reasons??recommendationReasons(current(),p.answers,p);return `<article class="match-card100"><div class="match-heading">${p.type?flower(p.type,'small'):''}<div><p class="eyebrow">${synthetic?'가상 응답 사례':'불러온 팀원 응답'}</p><h3>${esc(name)}</h3>${p.korean?`<p>${esc(p.korean)}</p>`:''}</div></div><div class="match-numbers"><span>내 선호 → 상대 <b>${p.ab.score===null?'미측정':Math.round(p.ab.score)}</b></span><span>상대 선호 → 나 <b>${p.ba.score===null?'미측정':Math.round(p.ba.score)}</b></span><span>상호 지표 <b>${p.score===null?'미측정':Math.round(p.score)}</b></span></div><p class="caption">${[...p.ab.excluded,...p.ba.excluded].includes('age')?'한쪽이 지정한 희망 나이 범위에 들지 않아요.':[...p.ab.unresolved,...p.ba.unresolved].includes('age')?'나이 제외 조건을 확인할 나이 정보나 유효한 희망 범위가 부족해요.':''}</p><p class="pair-status ${p.eligible?'':'muted'}">${p.eligible?'추천 기준을 통과한 사례예요.':p.ab.excluded.length||p.ba.excluded.length?'직접 고른 제외 조건에 해당해요.':p.ab.unresolved.length||p.ba.unresolved.length?'제외 조건을 판단할 정보가 부족해요.':p.ab.coverage<.7||p.ba.coverage<.7?'서로의 선호를 비교할 정보가 부족해요.':'현재 설정한 양방향 추천 기준에는 미치지 않아요.'}</p>${r.map(x=>`<div class="reason100"><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div>`).join('')}<details class="evidence100"><summary>항목별 추천 계산</summary><p class="caption">상호 지표는 연애 성공 확률이 아니에요. 동일한 꽃에 가산점을 주지 않아요.</p>${p.ab.domains.map(d=>`<p>${esc(d.name)} · 내 선호 충족 ${Math.round(d.fit*100)} · 비중 ${d.weight}</p>`).join('')}<p>내 선호 비교 정보 ${p.ab.observed}/${p.ab.informative} · 상대 ${p.ba.observed}/${p.ba.informative}</p></details></article>`;}
function result(){const a=current(),c=classifyAnswers(a),f=c.features,insights=readings(a),gaps=preferenceGaps(a),rec=recommendations(a),p=c.primary,complete=answeredCount(a)===100;return `${header()}<main id="main" class="page result100">${imported?`<div class="context-banner">불러온 결과: ${esc(imported.label)} · 내 저장 답변은 바뀌지 않아요.${imported.sourceModel&&imported.sourceModel!==model.version?` 저장 모델 ${esc(imported.sourceModel)}에서 현재 모델 ${model.version}로 다시 분석했어요.`:''}<button class="link-button" data-action="return-own">내 검사로 돌아가기</button></div>`:demo?`<div class="context-banner">초기 대표 프로필로 만든 가상 예시예요. 실제 참가자의 결과가 아니에요.<button class="link-button" data-action="start-own">직접 검사하기 →</button></div>`:''}${!complete?`<div class="context-banner">${answeredCount(a)}/100 답변 · 전체 결과를 보려면 남은 문항을 확인해 주세요. 이전 100문항 결과라면 변경된 종교·문신 4문항만 다시 확인하면 돼요.<button class="link-button" data-action="continue">남은 질문으로</button></div>`:''}<section class="portrait100"><div><p class="eyebrow">YOUR RELATIONSHIP PORTRAIT</p><h1 class="type-name" tabindex="-1">${p?p.type:c.status==='tied'?'BETWEEN FLOWERS':'아직 알아가는 중'}</h1><h2>${p?p.korean:c.status==='tied'?'여러 꽃에 비슷하게 가까워요':'유형을 정할 응답이 부족해요'}</h2><p>${c.status==='borderline'?'대표 유형과 두 번째 후보의 차이가 작아요. 두 유형의 특징을 함께 읽어주세요.':c.status==='tied'?`정확히 동점인 후보 ${c.tied.length}개를 확인했어요. 한 유형으로 강제 배정하지 않았어요.`:p?'25개 정보와 8개 영역을 비교한 초기 대표 유형이에요.':'미응답을 중간값으로 채우지 않아요. 질문을 더 확인해 주세요.'}</p></div>${p?flower(p.type):'<div class="neutral-flower" aria-hidden="true">✳</div>'}</section><button class="link-button" data-action="age">나이 정보·희망 범위 설정</button><nav class="result-nav"><a href="#personal">개인 분석</a><a href="#scores">세부 점수</a><a href="#wishes">원하는 상대</a><a href="#connections">추천 이유</a></nav><section class="result-section" id="personal"><p class="eyebrow">BETWEEN THE LINES</p><h2>같은 꽃이어도, 이런 점이 달라요</h2><div class="insights100">${insights.length?insights.map(x=>`<article class="insight100"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${evidence(x.evidence)}</article>`).join(''):'<p>개인 분석에 필요한 응답이 부족해요. 모르는 응답을 추측해 설명하지 않아요.</p>'}</div></section><section class="result-section" id="scores"><p class="eyebrow">YOUR CONTINUOUS PROFILE</p><h2>유형 하나에 담기지 않는 나</h2><div class="scores100">${scoreBars(f)}</div>${scoreEvidence()}<details class="type-ranking"><summary>16개 대표 프로필과 비교한 결과</summary><p>비교 지표는 유사한 정도를 표시한 값으로, 확률이나 신뢰도가 아니에요. 1·2위 차이가 3점 이하면 경계로 표시해요.</p>${c.ranking.map(r=>`<div class="ranking-row"><span>${r.type}<small>${r.korean}</small></span><div class="score-track"><i style="width:${r.fit}%"></i></div><b>${r.fit.toFixed(1)}</b></div>`).join('')||'<p>유형 비교에 충분한 정보가 아직 없어요.</p>'}<p class="caption">판정에 사용 가능한 정보 비중 ${Math.round(c.coverage*100)}% · ${c.groupsPresent}/8개 영역</p></details><details><summary>내 생활 응답 살펴보기</summary><div class="life100">${questions.filter(q=>q.id>=30&&q.id<=60).map(q=>`<div><span>${featureLabels['q'+q.id]}</span><strong>${esc(answerLabel(q.id,a[q.id]))}</strong></div>`).join('')}</div></details></section><section class="result-section" id="wishes"><p class="eyebrow">SOMEONE I FEEL AT EASE WITH</p><h2>내가 편안하게 느끼는 상대</h2><p>${Array.isArray(a[96])?`특히 중요하게 고른 영역: ${a[96].map(k=>domainDefs.find(d=>d.id===k)?.name).filter(Boolean).join(' · ')}`:a[96]==='any'?'여러 영역을 같은 비중으로 살펴봐요.':'중요하게 보는 영역은 아직 미측정이에요.'}</p><div class="gaps100">${gaps.map(g=>`<article><h3>${g.label}</h3><p>나의 응답: ${esc(g.self)}</p><p>원하는 상대: ${esc(g.wish)}</p><small>다르다고 보완 관계가 보장되지는 않아요.</small></article>`).join('')}</div><details><summary>내가 고른 상대 선호 전체 보기</summary><div class="life100">${questions.filter(q=>q.id>=61).map(q=>`<div><span>Q${q.id} · ${esc(q.text)}</span><strong>${esc(answerLabel(q.id,a[q.id]))}</strong></div>`).join('')}</div></details></section><section class="result-section" id="connections"><p class="eyebrow">A FEW POSSIBLE CONNECTIONS</p><h2>${rec.mode==='self-similarity'?'나와 비슷한 관계 방식의 유형':'내가 원하는 성향과 가까운 유형'}</h2><p class="context-banner">검사 결과를 이해하기 위한 참고 유형이에요. 나이·흡연·음주·종교·문신·자녀 계획 등 실제 상대 조건으로 유형을 제외하지 않아요. 실제 사람과의 매칭 성사나 상대의 선호를 보장하지 않아요.</p>${rec.mode==='self-similarity'?'<p class="caption">비교할 상대 성향 선호가 없어 내 성향과의 유사성으로 보여줘요.</p>':''}<div class="matches100">${rec.selected.map(typeCard).join('')||'<div class="empty100"><h3>유형을 비교할 성향 응답이 부족해요.</h3><p>나이 같은 제외 조건 때문이 아니에요. 성격·관계 응답이나 원하는 상대 성향을 더 확인해 주세요.</p></div>'}</div><div class="compare100"><h3>팀원 결과와 직접 비교하기</h3><p>실제 두 사람의 응답을 비교할 때는 양방향 점수와 나이·흡연 등 직접 고른 제외 조건을 별도로 확인해요. 파일은 서버에 보내지 않아요.</p><button class="button secondary" data-action="compare">팀원 결과 불러오기</button>${counterpart?pairCard({...pair(a,counterpart.answers,currentAge(),counterpart.ageProfile),answers:counterpart.answers,type:classifyAnswers(counterpart.answers).primary?.type,korean:classifyAnswers(counterpart.answers).primary?.korean},counterpart.label):''}</div></section><section class="result-section"><details class="type-catalog"><summary>16개 꽃 유형 둘러보기</summary><div class="mini-catalog">${model.prototypes.map(p=>`<button data-demo="${p.type}">${flower(p.type)}<strong>${p.type}</strong><span>${p.korean}</span></button>`).join('')}</div></details></section><div class="result-actions"><button class="button primary" data-action="edit">답변 돌아보기</button><button class="button secondary" data-action="export">결과 저장·공유</button>${demo?'<button class="button secondary" data-action="variant">다른 응답 예시</button>':'<button class="link-button" data-action="reset">새로 검사하기</button>'}</div></main>${footer()}`;}
function render(){app.innerHTML=view==='home'?home():view==='intro'?intro():view==='survey'?survey():result();}
function dialog(title,body){const d=document.createElement('dialog');d.className='dialog100';d.innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button data-close aria-label="닫기">×</button></div>${body}`;d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();return d;}
function navigator(){const a=current(),d=dialog('답변 돌아보기',[0,1].map(part=>`<h3>PART ${part+1} · ${partNames[part]}</h3><div class="jump100">${questions.filter(q=>(q.id<=60?0:1)===part).map(q=>`<button data-go="${q.id}" class="${validAnswer(q.id,a[q.id])?'filled':''}" aria-label="${q.id}번 ${validAnswer(q.id,a[q.id])?'답변 완료':'미응답'}">${q.id}</button>`).join('')}</div>`).join(''));d.addEventListener('click',e=>{if(e.target.closest('[data-go]'))d.close();});}
function payload(){const a=current(),c=classifyAnswers(a);return {wordingVersion,ageVersion,ageProfile:currentAge(),format:'suddenly-see-result-100',questionnaireVersion,modelVersion:model.version,previousResponses:imported?.previousResponses??previousResponses,sourceModelVersion:imported?.sourceModel??model.version,exportedAt:new Date().toISOString(),answers:sanitizeAnswers(a),result:{type:c.primary?.type??null,status:c.status},notice:'모든 원래 설문 응답이 포함됩니다. 공유할 상대를 확인해 주세요.'};}
function parse(text){text=text.replace(/^\uFEFF/,'').trim();if(text.includes('SIS100_RESULT_BEGIN'))text=text.split('SIS100_RESULT_BEGIN')[1].split('SIS100_RESULT_END')[0].trim();let obj;try{obj=JSON.parse(text);}catch{throw Error('JSON 파일 또는 이 검사에서 저장한 TXT·전달 텍스트를 사용해 주세요.');}if(!supportedVersions.includes(obj.questionnaireVersion)||obj.format!=='suddenly-see-result-100'){const error=Error('이전 검사 또는 다른 형식이에요. 이전 80문항 결과는 아래 이전 결과 화면에서 확인해 주세요. 새 문항의 답변을 추측해서 옮기지 않아요.');error.legacy=true;throw error;}if(!obj.answers||typeof obj.answers!=='object'||Array.isArray(obj.answers))throw Error('원래 응답이 없는 파일이에요.');const normalizedImport=normalizeRecord(obj),a=normalizedImport.answers;if(!Object.keys(obj.answers).length)throw Error('읽을 수 있는 응답이 없어요.');for(const [id,v] of Object.entries(obj.answers))if(!(obj.questionnaireVersion===previousVersion?validPriorAnswer(Number(id),v):validAnswer(Number(id),v)))throw Error(`${id}번 응답이 올바르지 않아요. 파일을 확인해 주세요.`);return {ageProfile:cleanAge(obj.ageProfile),answers:a,sourceModel:obj.modelVersion,previousResponses:normalizedImport.previousResponses,migratedIds:normalizedImport.migratedIds};}
function openImport(compare=false){const d=dialog(compare?'팀원 결과 불러오기':'결과 불러오기',`<p>새 100문항 검사의 JSON·TXT 파일 또는 전달 텍스트를 사용할 수 있어요. ${compare?'내 결과와 실제 응답을 비교해요.':'불러온 결과는 내 브라우저 답변을 덮어쓰지 않아요.'}</p><label class="file-label">결과 파일 선택<input type="file" accept=".json,.txt,application/json,text/plain"></label><label class="paste-label">전달 텍스트 붙여넣기<textarea rows="6" spellcheck="false"></textarea></label><button class="button primary" data-paste>불러오기</button><p class="import-status" role="status"></p><p><a href="./legacy.html">이전 80문항 검사·결과 화면으로 →</a></p>`),status=d.querySelector('.import-status');const load=(text,label)=>{try{if(text.length>2_000_000)throw Error('2MB 이하 결과 파일을 사용해 주세요.');const parsed=parse(text);if(parsed.migratedIds.length)label+=' · 종교·문신 변경 항목 미측정';if(compare){counterpart={...parsed,label};move('result');}else{if(!imported&&!demo)ownerIndex=index;imported={...parsed,label};demo=null;counterpart=null;move('result');}d.close();}catch(e){status.textContent=e.message;}};d.querySelector('input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000){status.textContent='2MB 이하 파일을 사용해 주세요.';return;}try{load(await file.text(),file.name.slice(0,120));}catch{status.textContent='파일을 읽지 못했어요. 붙여넣기를 이용해 주세요.';}e.target.value='';};d.querySelector('[data-paste]').onclick=()=>load(d.querySelector('textarea').value,'붙여넣은 결과');}
function openExport(){const json=JSON.stringify(payload(),null,2),c=classifyAnswers(current()),txt=`Suddenly I See — ${c.primary?.type??'유형 후보 확인 중'}\n100문항 결과 · ${model.version}\n이 파일에는 원래 설문 응답 전체가 들어 있어요.\n\nSIS100_RESULT_BEGIN\n${json}\nSIS100_RESULT_END`,name='suddenly-see-100-'+new Date().toISOString().replace(/[:.]/g,'-'),d=dialog('결과 저장·공유',`<p>원래 응답 전체가 포함돼요. 공유할 상대를 확인해 주세요. 휴대폰에서 JSON이 저장되지 않으면 TXT·공유·복사를 이용해 주세요.</p><div class="dialog-actions"><button class="button primary" data-save="txt">TXT 저장</button><button class="button secondary" data-save="share">휴대폰 공유</button><button class="button secondary" data-save="copy">결과 복사</button><button class="link-button" data-save="json">JSON 저장</button></div><p class="export-status" role="status"></p><details class="manual"><summary>복사·공유가 안 될 때 직접 선택</summary><textarea rows="7" readonly></textarea><button class="button secondary" data-select>텍스트 전체 선택</button></details>`),status=d.querySelector('.export-status'),area=d.querySelector('textarea');area.value=txt;const manual=msg=>{status.textContent=msg;d.querySelector('.manual').open=true;area.focus();area.select();area.setSelectionRange(0,area.value.length);};d.querySelector('[data-select]').onclick=()=>manual('기기의 복사 메뉴로 선택한 텍스트를 복사해 주세요.');d.addEventListener('click',async e=>{const act=e.target.closest('[data-save]')?.dataset.save;if(!act)return;try{if(act==='copy'){if(!navigator.clipboard?.writeText){manual('자동 복사를 사용할 수 없어요. 직접 선택해 주세요.');return;}await navigator.clipboard.writeText(txt);status.textContent='결과 전달 텍스트를 복사했어요.';}else if(act==='share'){if(!navigator.share){manual('이 브라우저에서 공유 메뉴를 사용할 수 없어요. 텍스트를 복사해 주세요.');return;}const file=new File(['\uFEFF'+txt],name+'.txt',{type:'text/plain'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'Suddenly I See 검사 결과'});else await navigator.share({title:'Suddenly I See 검사 결과',text:txt});status.textContent='공유 요청을 전달했어요.';}else{const blob=new Blob([act==='json'?json:'\uFEFF'+txt],{type:act==='json'?'application/json':'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.'+act;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='저장을 요청했어요. 기기의 파일·다운로드 앱에서 확인해 주세요.';}}catch(e){if(e.name==='AbortError')status.textContent='공유를 취소했어요.';else manual('공유·복사를 완료하지 못했어요. 아래 텍스트를 직접 선택해 주세요.');}});}
document.addEventListener('change',e=>{const input=e.target.closest('[data-question]');if(!input)return;const id=Number(input.dataset.question),q=byId[id],raw=input.dataset.value,value=/^[1-5]$/.test(raw)?Number(raw):raw,a=current();if(q.kind==='multi'&&value!=='any'&&value!=='unknown'){const set=new Set(Array.isArray(a[id])?a[id]:[]);input.checked?set.add(value):set.delete(value);if(set.size>q.max){input.checked=false;toast(`최대 ${q.max}개까지 골라주세요.`);return;}if(set.size)a[id]=[...set];else delete a[id];}else a[id]=value;persist();render();document.getElementById(input.id)?.focus({preventScroll:true});});
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){e.preventDefault();completing=false;index=Number(go.dataset.go)-1;move('survey');return;}const target=e.target.closest('button');if(!target||target.disabled)return;if(target.dataset.demo){if(!demo&&!imported)ownerIndex=index;demo={type:target.dataset.demo,variant:0,answers:demoAnswers(target.dataset.demo)};imported=null;counterpart=null;move('result');return;}const action=target.dataset.action;if(action==='age')openAge();if(action==='home'){if(imported||demo)index=ownerIndex??index;imported=null;demo=null;ownerIndex=null;counterpart=null;move('home');}if(action==='start'||action==='start-own'){if(imported||demo)index=ownerIndex??index;imported=null;demo=null;ownerIndex=null;counterpart=null;if(answeredCount(answers)===100)move('result');else{completing=answeredCount(answers)>0;index=Math.max(0,questions.findIndex(q=>!validAnswer(q.id,answers[q.id])));move(answeredCount(answers)===0?'intro':'survey');}}if(action==='part-start')move('survey');if(action==='next'){if(!validAnswer(questions[index].id,current()[questions[index].id]))return;if(completing){const oldPart=index<60?0:1,remaining=questions.findIndex(q=>!validAnswer(q.id,current()[q.id]));if(remaining<0){completing=false;move('result');}else{index=remaining;move((index<60?0:1)!==oldPart?'intro':'survey');}return;}if(index===99){const missing=questions.findIndex(q=>!validAnswer(q.id,current()[q.id]));if(missing>=0){index=missing;move('survey');toast('아직 답하지 않은 질문을 확인해 주세요.');}else move('result');}else{index++;move(index===60?'intro':'survey');}}if(action==='previous'&&index>0){index--;move('survey');}if(action==='navigator'||action==='edit')navigator();if(action==='continue'){completing=true;const missing=questions.findIndex(q=>!validAnswer(q.id,current()[q.id])||current()[q.id]==='unknown');index=Math.max(0,missing);move('survey');}if(action==='demo'){if(!demo&&!imported)ownerIndex=index;imported=null;demo={type:'STEADYSPARK',variant:0,answers:demoAnswers('STEADYSPARK')};counterpart=null;move('result');}if(action==='variant'&&demo){demo.variant=1-demo.variant;demo.answers=demoAnswers(demo.type,demo.variant);move('result');}if(action==='return-own'){index=ownerIndex??index;ownerIndex=null;imported=null;counterpart=null;view='home';render();window.scrollTo(0,0);}if(action==='import')openImport();if(action==='compare')openImport(true);if(action==='export')openExport();if(action==='reset'){const d=dialog('새로 검사할까요?','<p>이번 100문항 검사 답변만 지워요. 이전 80문항 결과는 그대로 보존해요.</p><button class="button primary" data-confirm>지우고 시작하기</button>');d.querySelector('[data-confirm]').onclick=()=>{imported=null;demo=null;counterpart=null;answers={};ageProfile=cleanAge(null);previousResponses=[];completing=false;index=0;d.close();move('intro');};}});
render();
